package com.ddownloader.android.storage

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.booleanOrNull
import kotlinx.serialization.json.intOrNull
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Differential parity gate for the Jellyfin layout/rename port.
 *
 * `app/src/test/resources/media-layout-vectors.json` is generated by running the
 * ORIGINAL `electron/media-layout.ts` (compiled with tsc, unmodified) over a
 * 16-name corpus — see `EVIDENCE/parity/media-layout.js` and
 * `scripts/gen-media-layout-vectors.js`. This test asserts the Kotlin port
 * reproduces every title / year / season / folder string exactly, including the
 * odd edge cases the original has ("1923.S01.1080p" yields year 1923).
 */
class MediaLayoutParityTest {

    private val vectors: JsonObject by lazy {
        val text = javaClass.classLoader!!.getResourceAsStream("media-layout-vectors.json")!!
            .bufferedReader().use { it.readText() }
        Json.parseToJsonElement(text).jsonObject
    }

    private fun intOrNull(obj: JsonObject, key: String): Int? =
        obj[key]?.jsonPrimitive?.let { if (it.content == "null") null else it.intOrNull }

    private fun strOrNull(obj: JsonObject, key: String): String? =
        obj[key]?.jsonPrimitive?.let { if (it.content == "null") null else it.content }

    @Test
    fun `parseReleaseName matches the TypeScript oracle`() {
        var checked = 0
        vectors["cases"]!!.jsonArray.forEach { el ->
            val c = el.jsonObject
            val input = c["input"]!!.jsonPrimitive.content
            val parsed = MediaLayout.parseReleaseName(input)
            assertEquals("title for <$input>", c["title"]!!.jsonPrimitive.content, parsed.title)
            assertEquals("year for <$input>", intOrNull(c, "year"), parsed.year)
            assertEquals("season for <$input>", intOrNull(c, "season"), parsed.season)
            checked++
        }
        assertEquals(16, checked)
    }

    @Test
    fun `series destination matches the TypeScript oracle`() {
        vectors["cases"]!!.jsonArray.forEach { el ->
            val c = el.jsonObject
            val input = c["input"]!!.jsonPrimitive.content
            val dest = MediaLayout.computeDestination(MediaLayout.Kind.SERIES, input, null, null)
            assertEquals("series folder for <$input>", c["seriesFolder"]!!.jsonPrimitive.content, dest.relativePath)
            assertEquals("series season for <$input>", intOrNull(c, "seriesSeason"), dest.season)
        }
    }

    @Test
    fun `movie destination matches the TypeScript oracle`() {
        vectors["cases"]!!.jsonArray.forEach { el ->
            val c = el.jsonObject
            val input = c["input"]!!.jsonPrimitive.content
            val dest = MediaLayout.computeDestination(MediaLayout.Kind.MOVIE, input, null, null)
            assertEquals("movie folder for <$input>", c["movieFolder"]!!.jsonPrimitive.content, dest.relativePath)
        }
    }

    @Test
    fun `season override wins over the parsed season`() {
        vectors["cases"]!!.jsonArray.forEach { el ->
            val c = el.jsonObject
            val input = c["input"]!!.jsonPrimitive.content
            val dest = MediaLayout.computeDestination(MediaLayout.Kind.SERIES, input, null, 2)
            assertEquals("override folder for <$input>", c["overrideFolder"]!!.jsonPrimitive.content, dest.relativePath)
        }
    }

    @Test
    fun `safeSegment matches the TypeScript oracle`() {
        vectors["safeSegments"]!!.jsonArray.forEach { el ->
            val c = el.jsonObject
            val input = c["input"]!!.jsonPrimitive.content
            val expected = c["output"]!!.jsonPrimitive.content
            assertEquals("safeSegment(<$input>)", expected, MediaLayout.safeSegment(input))
        }
    }

    @Test
    fun `tmdb override changes the folder without touching the release parser`() {
        val dest = MediaLayout.computeDestination(
            MediaLayout.Kind.SERIES,
            "Breaking.Bad.2008.S01E02.1080p.WEB-DL.x264-GROUP",
            tmdb = "Breaking Bad" to 2008,
            seasonOverride = 1,
        )
        assertEquals("Breaking Bad (2008)/Season 01", dest.relativePath)
    }

    @Test
    fun `unknown release name still yields a usable title`() {
        val parsed = MediaLayout.parseReleaseName("_____")
        assertEquals("Unknown", parsed.title)
    }

    @Suppress("unused")
    private fun booleanFlag(obj: JsonObject, key: String): Boolean? =
        obj[key]?.jsonPrimitive?.booleanOrNull
}
